import { observer } from 'mobx-react-lite';
import React, { useEffect, useState } from 'react';
import { useContext } from 'react';
import { Context } from '../index';
import { Button, Card, Col, Container, Form, Row, Spinner } from 'react-bootstrap'
import { getOrder } from '../http/orderAPI';
import { useHistory } from 'react-router-dom/cjs/react-router-dom';
import { ORDER_ROUTE } from '../utils/consts';

const Orders = observer(() => {
  const {order} = useContext(Context)
  const {user} = useContext(Context)

  const history = useHistory()
  const [loading, setLoading] = useState(true)
  const [viewType, setViewType] = useState(false)


  function stop(){
    setLoading(false)
  }

  function click(){
    {
      viewType ?
      setViewType(false)
      :
      setViewType(true)
    }
  }

  useEffect(() =>{
      user.user.role === 'ADMIN' ?
        viewType ?
          getOrder(order.page, order.limit).then(data => {
            order.setAllOrders(data.rows.oneUser)
            order.setTotalCount(data.count)
          }).finally(setTimeout(stop, 1000))
        :
          getOrder(order.page, order.limit).then(data => {
            order.setAllOrders(data.rows.allUsers)
            order.setTotalCount(data.count)
          }).finally(setTimeout(stop, 1000))
      :
        getOrder(order.page, order.limit).then(data => {
          order.setAllOrders(data.rows.oneUser)
          order.setTotalCount(data.count)
        }).finally(setTimeout(stop, 1000))
  }, [viewType])

  if (loading){
    return <Spinner animation={"grow"}/>
  }

  function color(status){
    switch(status){
      case 'Нове':
        return 'primary'
      case 'Відхилено':
        return 'danger'
      case 'Прийняте':
        return 'info'
      case 'Готується':
        return 'warning'
      case 'В доставці':
        return 'secondary'
      case 'Виконано':
        return 'success'
    }
  }

  return (
    <Container className="min-vh-100 d-flex flex-sm-column mt-3">
      {user.user.role === 'ADMIN' ?
        <Form>
        <Form.Check
          type="switch"
          id="custom-switch"
          label={viewType ? "Мої замовлення" : "Усі замовлення"}
          onChange={()=> click()}
        />
        </Form>
      :
        []
      }
      
      {order.allOrders === [] ?
        <h1 className="pb-2">Замовлень немає ☹</h1>
      :
      <Container>
        {console.log(order.allOrders)}
        {order.allOrders.map(oneOrder =>
        <Container key={oneOrder.id}> 
          <Card text='light' style={{cursor:'pointer'}} bg={color(oneOrder.status)} onClick={() => history.push(ORDER_ROUTE +  '/' + oneOrder.id)}>
          <Card.Header>{oneOrder.status}</Card.Header>
            <Card.Body>
              <Card.Title>Замовлення №{oneOrder.id}</Card.Title>
            </Card.Body>
          </Card>
          <hr/>
          </Container>
        )}
      </Container>
      }
    </Container>
  );
});

export default Orders;
